import { Component } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';

export default class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error('ErrorBoundary caught:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
          <div className="max-w-md w-full bg-white rounded-2xl shadow-lg p-8 text-center">
            <div className="flex items-center justify-center w-16 h-16 bg-red-100 rounded-full mx-auto mb-4">
              <AlertTriangle className="h-8 w-8 text-red-600" />
            </div>
            <h2 className="text-xl font-bold text-gray-900 mb-2">Terjadi Kesalahan</h2>
            <p className="text-gray-500 text-sm mb-6">
              Maaf, terjadi kesalahan yang tidak terduga. Silakan muat ulang halaman.
            </p>
            <button
              onClick={() => window.location.reload()}
              className="inline-flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 transition-colors"
            >
              <RefreshCw className="h-4 w-4" />
              Muat Ulang Halaman
            </button>
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details className="mt-4 text-left">
                <summary className="text-sm text-gray-500 cursor-pointer hover:text-gray-700">Detail Error</summary>
                <pre className="mt-2 p-3 bg-gray-100 rounded-lg text-xs text-red-600 overflow-auto max-h-40">
                  {this.state.error.toString()}
                </pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import { useRef, useState, useEffect } from 'react';
import { RotateCcw, Check, Edit3 } from 'lucide-react';

export default function SignaturePad({ label, value, onChange }) {
  const canvasRef = useRef(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isEmpty, setIsEmpty] = useState(true);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#1e1b4b'; // Deep navy signature color

    // If initial value exists as base64 image
    if (value) {
      const img = new Image();
      img.onload = () => {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        setIsEmpty(false);
      };
      img.src = value;
    }
  }, []);

  const getPos = (e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    return {
      x: (clientX - rect.left) * (canvas.width / rect.width),
      y: (clientY - rect.top) * (canvas.height / rect.height),
    };
  };

  const startDrawing = (e) => {
    e.preventDefault();
    setIsDrawing(true);
    const pos = getPos(e);
    const ctx = canvasRef.current.getContext('2d');
    ctx.beginPath();
    ctx.moveTo(pos.x, pos.y);
  };

  const draw = (e) => {
    if (!isDrawing) return;
    e.preventDefault();
    const pos = getPos(e);
    const ctx = canvasRef.current.getContext('2d');
    ctx.lineTo(pos.x, pos.y);
    ctx.stroke();
    setIsEmpty(false);
  };

  const stopDrawing = () => {
    if (!isDrawing) return;
    setIsDrawing(false);
    const canvas = canvasRef.current;
    if (onChange) {
      onChange(canvas.toDataURL('image/png'));
    }
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setIsEmpty(true);
    if (onChange) {
      onChange('');
    }
  };

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <label className="block text-xs font-bold text-gray-800 flex items-center gap-1.5">
          <Edit3 className="h-3.5 w-3.5 text-indigo-600" />
          {label || 'Tanda Tangan Digital'}
        </label>
        {!isEmpty && (
          <button
            type="button"
            onClick={clearCanvas}
            className="text-xs text-red-600 hover:text-red-700 flex items-center gap-1 font-semibold transition"
          >
            <RotateCcw className="h-3 w-3" /> Hapus / Ulangi
          </button>
        )}
      </div>

      <div className="relative bg-slate-50 border-2 border-dashed border-gray-300 rounded-2xl overflow-hidden hover:border-indigo-400 transition">
        <canvas
          ref={canvasRef}
          width={400}
          height={160}
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
          className="w-full h-40 cursor-crosshair touch-none"
        />

        {isEmpty && (
          <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center text-gray-400">
            <Edit3 className="h-6 w-6 mb-1 opacity-40" />
            <p className="text-xs font-medium">Tanda tangan di sini menggunakan mouse / sentuhan</p>
          </div>
        )}
      </div>
    </div>
  );
}

import { Inbox, Clock, CheckCircle2, TrendingUp, AlertCircle, ArrowUpRight } from 'lucide-react';

export default function FinanceStats({
  bookingBaru = 12,
  menungguPembayaran = 8,
  sudahLunas = 45,
  pendapatanBulanIni = 85000000
}) {
  const stats = [
    {
      title: 'Booking Baru',
      value: bookingBaru,
      badge: '+3 Hari Ini',
      badgeColor: 'bg-blue-50 text-blue-700 border-blue-200/60',
      icon: Inbox,
      iconBg: 'bg-blue-50 text-blue-600',
      description: 'Otomatis masuk dari Admin Booking',
    },
    {
      title: 'Menunggu Pembayaran',
      value: menungguPembayaran,
      badge: 'Perlu Konfirmasi',
      badgeColor: 'bg-amber-50 text-amber-700 border-amber-200/60',
      icon: Clock,
      iconBg: 'bg-amber-50 text-amber-600',
      description: 'Menunggu verifikasi bukti/bayar',
    },
    {
      title: 'Sudah Lunas',
      value: sudahLunas,
      badge: 'Verified',
      badgeColor: 'bg-emerald-50 text-emerald-700 border-emerald-200/60',
      icon: CheckCircle2,
      iconBg: 'bg-emerald-50 text-emerald-600',
      description: 'Pembayaran selesai & terverifikasi',
    },
    {
      title: 'Pendapatan Bulan Ini',
      value: `Rp ${Number(pendapatanBulanIni).toLocaleString('id-ID')}`,
      badge: '+18% vs Bln Lalu',
      badgeColor: 'bg-indigo-50 text-indigo-700 border-indigo-200/60',
      icon: TrendingUp,
      iconBg: 'bg-indigo-50 text-indigo-600',
      description: 'Total pemasukan rental terkonfirmasi',
    },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
      {stats.map((stat, idx) => {
        const Icon = stat.icon;
        return (
          <div
            key={idx}
            className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm hover:shadow-md transition-all duration-200 flex flex-col justify-between"
          >
            <div>
              <div className="flex items-center justify-between mb-3">
                <div className={`w-11 h-11 rounded-xl flex items-center justify-center ${stat.iconBg}`}>
                  <Icon className="h-5 w-5" />
                </div>
                <span className={`text-xs px-2.5 py-1 rounded-full font-semibold border ${stat.badgeColor}`}>
                  {stat.badge}
                </span>
              </div>
              <p className="text-xs font-medium text-gray-500 uppercase tracking-wider">{stat.title}</p>
              <h3 className="text-2xl font-extrabold text-gray-900 mt-1 tracking-tight">{stat.value}</h3>
            </div>
            <p className="text-xs text-gray-400 mt-3 pt-3 border-t border-gray-50 flex items-center gap-1">
              <span>{stat.description}</span>
            </p>
          </div>
        );
      })}
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Sidebar from './Sidebar';
import { Menu, Bell, CheckCheck, Clock, ExternalLink, X, ShoppingBag, CreditCard, CheckCircle2 } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

export default function AppLayout({ children }) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const notifRef = useRef(null);
  const { user, isAdmin, isKeuangan } = useAuth();
  const navigate = useNavigate();

  // Role-based Initial Notifications
  const initialNotifications = isAdmin ? [
    {
      id: 1,
      title: 'Pemesanan Baru #BKG-2026-001',
      desc: 'Customer Aji melakukan booking Excavator CAT 320D.',
      time: '5 menit lalu',
      unread: true,
      link: '/admin/bookings',
      icon: ShoppingBag,
      color: 'bg-indigo-50 text-indigo-600'
    },
    {
      id: 2,
      title: 'Pengembalian Unit Alat',
      desc: 'Alat Total Station TS06 telah dikembalikan tepat waktu.',
      time: '45 menit lalu',
      unread: true,
      link: '/admin/logbook',
      icon: CheckCircle2,
      color: 'bg-emerald-50 text-emerald-600'
    },
    {
      id: 3,
      title: 'Customer Baru Terdaftar',
      desc: 'Customer Budi (yanti3@gmail.com) menyelesaikan registrasi.',
      time: '2 jam lalu',
      unread: false,
      link: '/admin/customers',
      icon: Bell,
      color: 'bg-violet-50 text-violet-600'
    }
  ] : isKeuangan ? [
    {
      id: 1,
      title: 'Verifikasi Pembayaran INV-2026-001',
      desc: 'Customer melakukan transfer sebesar Rp 7.500.000 via BCA.',
      time: '10 menit lalu',
      unread: true,
      link: '/finance/pembayaran',
      icon: CreditCard,
      color: 'bg-indigo-50 text-indigo-600'
    },
    {
      id: 2,
      title: 'Booking Masuk Siap Invoice',
      desc: 'Booking #BKG-2026-002 memerlukan penerbitan invoice resmi.',
      time: '1 jam lalu',
      unread: true,
      link: '/finance/booking-masuk',
      icon: ShoppingBag,
      color: 'bg-amber-50 text-amber-600'
    }
  ] : [
    {
      id: 1,
      title: 'Booking Anda Dikonfirmasi! 🎉',
      desc: 'Booking Excavator CAT 320D telah disetujui oleh Admin.',
      time: '15 menit lalu',
      unread: true,
      link: '/bookings',
      icon: CheckCircle2,
      color: 'bg-emerald-50 text-emerald-600'
    },
    {
      id: 2,
      title: 'Pembayaran Lunas',
      desc: 'Invoice #INV-2026-001 telah diverifikasi oleh Admin Finance.',
      time: '2 jam lalu',
      unread: true,
      link: '/pembayaran',
      icon: CreditCard,
      color: 'bg-indigo-50 text-indigo-600'
    }
  ];

  const [notifications, setNotifications] = useState(initialNotifications);
  const unreadCount = notifications.filter(n => n.unread).length;

  // Handle click outside notification dropdown to close
  useEffect(() => {
    function handleClickOutside(event) {
      if (notifRef.current && !notifRef.current.contains(event.target)) {
        setShowNotifications(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleMarkAllRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, unread: false })));
  };

  const handleNotificationClick = (link, id) => {
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, unread: false } : n));
    setShowNotifications(false);
    if (link) navigate(link);
  };

  return (
    <div className="flex h-screen bg-slate-900/5 overflow-hidden">
      <Sidebar mobileOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Glassmorphic Top Navbar */}
        <header className="h-20 bg-white/80 backdrop-blur-xl border-b border-gray-200/60 flex items-center justify-between px-4 sm:px-8 flex-shrink-0 z-30 shadow-sm">
          <div className="flex items-center gap-3">
            <button
              onClick={() => setSidebarOpen(true)}
              className="md:hidden p-2.5 rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors"
            >
              <Menu className="h-5 w-5" />
            </button>
            <div className="hidden sm:flex items-center gap-2 text-xs font-extrabold text-slate-500 bg-slate-100/80 border border-slate-200/60 px-3.5 py-1.5 rounded-full">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-ping"></span>
              Sistem Rental Alat Heavy Equipment Online
            </div>
          </div>

          <div className="flex items-center gap-3 ml-auto">
            {/* INTERACTIVE NOTIFICATION BELL & DROPDOWN */}
            <div className="relative" ref={notifRef}>
              <button
                onClick={() => setShowNotifications(!showNotifications)}
                className={`relative p-2.5 rounded-2xl transition-all cursor-pointer border border-slate-200/60 ${
                  showNotifications
                    ? 'bg-indigo-600 text-white border-indigo-600 shadow-md shadow-indigo-500/20'
                    : 'bg-slate-100/80 hover:bg-indigo-50 text-slate-600 hover:text-indigo-600'
                }`}
                title="Pemberitahuan Sistem"
              >
                <Bell className="h-4 w-4" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-rose-500 text-[9px] font-black text-white ring-2 ring-white animate-pulse">
                    {unreadCount}
                  </span>
                )}
              </button>

              {/* NOTIFICATIONS DROPDOWN MENU */}
              {showNotifications && (
                <div className="absolute right-0 mt-3 w-80 sm:w-96 rounded-3xl bg-white border border-gray-100 shadow-2xl z-50 animate-scale-in overflow-hidden">
                  {/* Dropdown Header */}
                  <div className="flex items-center justify-between p-4 bg-slate-50 border-b border-gray-100">
                    <div className="flex items-center gap-2">
                      <h3 className="text-sm font-black text-slate-900">Notifikasi System</h3>
                      {unreadCount > 0 && (
                        <span className="bg-indigo-100 text-indigo-700 text-[10px] font-extrabold px-2 py-0.5 rounded-full">
                          {unreadCount} Baru
                        </span>
                      )}
                    </div>

                    {unreadCount > 0 && (
                      <button
                        onClick={handleMarkAllRead}
                        className="text-[11px] font-bold text-indigo-600 hover:text-indigo-800 flex items-center gap-1 cursor-pointer transition-colors"
                      >
                        <CheckCheck className="h-3.5 w-3.5" /> Tandai Dibaca
                      </button>
                    )}
                  </div>

                  {/* Notification Items List */}
                  <div className="max-h-80 overflow-y-auto divide-y divide-gray-50">
                    {notifications.length > 0 ? (
                      notifications.map(n => {
                        const Icon = n.icon;
                        return (
                          <div
                            key={n.id}
                            onClick={() => handleNotificationClick(n.link, n.id)}
                            className={`p-4 hover:bg-indigo-50/50 transition-all cursor-pointer flex gap-3 items-start group ${
                              n.unread ? 'bg-indigo-50/20' : ''
                            }`}
                          >
                            <div className={`p-2.5 rounded-2xl ${n.color} flex-shrink-0 group-hover:scale-110 transition-transform`}>
                              <Icon className="h-4 w-4" />
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center justify-between gap-1">
                                <p className={`text-xs font-bold text-slate-900 truncate ${n.unread ? 'font-black text-indigo-950' : ''}`}>
                                  {n.title}
                                </p>
                                {n.unread && (
                                  <span className="w-2 h-2 rounded-full bg-indigo-600 flex-shrink-0"></span>
                                )}
                              </div>
                              <p className="text-xs text-slate-500 mt-0.5 leading-relaxed line-clamp-2">
                                {n.desc}
                              </p>
                              <div className="flex items-center gap-1 mt-1.5 text-[10px] font-medium text-slate-400">
                                <Clock className="h-3 w-3 text-slate-400" />
                                <span>{n.time}</span>
                              </div>
                            </div>
                          </div>
                        );
                      })
                    ) : (
                      <div className="p-8 text-center text-slate-400 text-xs">
                        Tidak ada pemberitahuan baru saat ini.
                      </div>
                    )}
                  </div>

                  {/* Dropdown Footer */}
                  <div className="p-3 bg-slate-50 border-t border-gray-100 text-center">
                    <button
                      onClick={() => setShowNotifications(false)}
                      className="text-xs font-bold text-slate-600 hover:text-indigo-600 transition-colors"
                    >
                      Tutup Notifikasi
                    </button>
                  </div>
                </div>
              )}
            </div>

            {/* Profile Badge */}
            <div 
              onClick={() => navigate('/profile')}
              className="flex items-center gap-3 p-1.5 pr-3 rounded-2xl bg-white border border-gray-200/80 shadow-sm hover:shadow-md transition-all cursor-pointer"
            >
              <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-600 flex items-center justify-center text-white font-extrabold text-sm shadow-md shadow-indigo-500/20">
                {user?.nama?.charAt(0).toUpperCase()}
              </div>
              <div className="hidden sm:block text-left">
                <p className="text-xs font-extrabold text-slate-900 leading-tight">{user?.nama}</p>
                <p className="text-[10px] font-bold text-indigo-600 uppercase tracking-wider">{user?.role}</p>
              </div>
            </div>
          </div>
        </header>

        {/* Page Content Container */}
        <main className="flex-1 overflow-y-auto">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}

import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import {
  LayoutDashboard, Wrench, Tag, ShoppingCart, CreditCard, RotateCcw,
  Users, LogOut, User, ChevronRight, X, ShoppingBag, Table,
  Inbox, FileText, History, BarChart3, Receipt
} from 'lucide-react';

const adminMenu = [
  { to: '/admin',              icon: LayoutDashboard, label: 'Dashboard' },
  { to: '/alat',               icon: ShoppingBag,     label: 'Form Booking Alat' },
  { to: '/admin/kategori',     icon: Tag,             label: 'Kategori Alat' },
  { to: '/admin/alat',         icon: Wrench,          label: 'Data Alat' },
  { to: '/admin/customers',    icon: Users,           label: 'Kelola Customer' },
  { to: '/admin/bookings',     icon: ShoppingCart,    label: 'Data Booking' },
  { to: '/admin/users',        icon: Users,           label: 'Semua User' },
  { to: '/admin/logbook',      icon: Table,           label: 'Log Book Rental' },
];

const keuanganMenu = [
  { to: '/finance',                 icon: LayoutDashboard, label: 'Dashboard Finance' },
  { to: '/finance/booking-masuk',   icon: Inbox,           label: 'Booking Masuk' },
  { to: '/finance/pembayaran',      icon: CreditCard,      label: 'Pembayaran' },
  { to: '/finance/invoice',         icon: FileText,        label: 'Invoice' },
  { to: '/finance/riwayat-transaksi', icon: History,       label: 'Riwayat Transaksi' },
  { to: '/finance/laporan-keuangan',  icon: BarChart3,     label: 'Laporan Keuangan' },
];

const customerMenu = [
  { to: '/dashboard',  icon: LayoutDashboard, label: 'Dashboard' },
  { to: '/alat',       icon: Wrench,          label: 'Sewa Alat' },
  { to: '/bookings',   icon: ShoppingCart,    label: 'Booking Saya' },
  { to: '/pembayaran', icon: CreditCard,      label: 'Pembayaran' },
];

export default function Sidebar({ mobileOpen, onClose }) {
  const { user, logout, isAdmin, isKeuangan } = useAuth();
  const navigate = useNavigate();
  
  let menu = customerMenu;
  if (isAdmin) menu = adminMenu;
  else if (isKeuangan) menu = keuanganMenu;

  const handleLogout = () => { logout(); navigate('/login'); };

  return (
    <>
      {/* Mobile overlay */}
      {mobileOpen && (
        <div className="fixed inset-0 bg-black/40 z-40 md:hidden" onClick={onClose} />
      )}

      <aside className={`
        fixed top-0 left-0 h-full w-64 bg-slate-900 text-slate-300 border-r border-slate-800/80 z-50 flex flex-col
        transition-transform duration-300 ease-in-out shadow-2xl
        md:translate-x-0 md:sticky md:top-0 md:h-screen
        ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        {/* Logo */}
        <div className="flex items-center justify-between px-6 h-20 border-b border-slate-800/80 flex-shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-tr from-indigo-600 via-indigo-500 to-violet-500 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-500/30">
              <Wrench className="h-5 w-5 text-white stroke-[2.5]" />
            </div>
            <div>
              <span className="text-xl font-black tracking-tight text-white">Rental<span className="bg-gradient-to-r from-indigo-400 to-violet-400 bg-clip-text text-transparent">Hub</span></span>
              <span className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest -mt-0.5">Heavy Equipment</span>
            </div>
          </div>
          <button onClick={onClose} className="md:hidden p-2 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800">
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* User Info Card */}
        <div className="px-4 py-4 border-b border-slate-800/80 flex-shrink-0">
          <div className="flex items-center gap-3 p-3.5 rounded-2xl bg-gradient-to-r from-slate-800/90 to-indigo-950/40 border border-slate-700/50 shadow-inner">
            <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center text-white font-extrabold text-sm shadow-md shadow-indigo-500/20 flex-shrink-0">
              {user?.nama?.charAt(0).toUpperCase()}
            </div>
            <div className="min-w-0">
              <p className="text-sm font-bold text-white truncate">{user?.nama}</p>
              <span className="inline-flex items-center gap-1 text-[10px] font-bold text-indigo-300 bg-indigo-500/20 px-2 py-0.5 rounded-md uppercase tracking-wider">
                <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse"></span>
                {user?.role}
              </span>
            </div>
          </div>
        </div>

        {/* Nav Menu */}
        <nav className="flex-1 overflow-y-auto px-3.5 py-4 space-y-1">
          {menu.map(({ to, icon: Icon, label }) => (
            <NavLink
