import { createContext, useContext, useState, useEffect } from 'react';
import api from '../lib/api';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    try {
      const stored = localStorage.getItem('user');
      return stored ? JSON.parse(stored) : null;
    } catch {
      return null;
    }
  });
  const [loading, setLoading] = useState(false);

  const login = async (email, password) => {
    setLoading(true);
    try {
      const res = await api.post('/auth/login', { email, password });
      const { token, user: userData } = res.data.data;
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(userData));
      setUser(userData);
      return { success: true, role: userData.role };
    } catch (err) {
      return { success: false, message: err.response?.data?.message || 'Login gagal' };
    } finally {
      setLoading(false);
    }
  };

  const register = async (data) => {
    setLoading(true);
    try {
      const res = await api.post('/auth/register', data);
      return { success: true, data: res.data };
    } catch (err) {
      return { success: false, message: err.response?.data?.message || 'Registrasi gagal' };
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
  };

  const refreshProfile = async () => {
    try {
      const res = await api.get('/auth/profile');
      const updated = {
        id: res.data.data.id,
        nama: res.data.data.nama,
        email: res.data.data.email,
        no_hp: res.data.data.no_hp,
        alamat: res.data.data.alamat,
        foto: res.data.data.foto,
        status: res.data.data.status,
        role: res.data.data.role?.nama_role,
      };
      localStorage.setItem('user', JSON.stringify(updated));
      setUser(updated);
    } catch {}
  };

  const roleLower = user?.role?.toLowerCase() || '';
  const isAdmin = roleLower === 'admin';
  const isKeuangan = roleLower === 'keuangan' || roleLower === 'finance' || roleLower === 'admin_finance' || roleLower === 'admin finance';
  const isAdminFinance = isKeuangan;
  const isStaff = isAdmin || isKeuangan;

  return (
    <AuthContext.Provider value={{ user, loading, login, register, logout, refreshProfile, isAdmin, isKeuangan, isAdminFinance, isStaff }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

