  const [recentBookings, setRecent] = useState([]);
  const [pendingPay, setPending]    = useState([]);
  const [loading, setLoading]       = useState(true);

  useEffect(() => {
    (async () => {
      try {
        const [bRes, uRes, aRes, pRes] = await Promise.all([
          api.get('/bookings?size=100'),
          api.get('/users?size=100'),
          api.get('/alat?size=100'),
          api.get('/pembayaran?size=100'),
        ]);
        const b = bRes.data.data, u = uRes.data.data, a = aRes.data.data, p = pRes.data.data;
        setStats({
          totalBooking: b.length,
          totalUser: u.length,
          totalAlat: a.length,
          pendingBooking: b.filter(x => x.status === 'pending').length,
          pendingPay: p.filter(x => x.status === 'menunggu').length,
          revenue: p.filter(x => x.status === 'lunas').reduce((s, x) => s + Number(x.jumlah), 0),
          alatTersedia: a.filter(x => x.status === 'tersedia').length,
        });
        setRecent(b.slice(0, 6));
        setPending(p.filter(x => x.status === 'menunggu').slice(0, 5));
      } catch {}
      setLoading(false);
    })();
  }, []);

  return (
    <AppLayout>
      <div className="animate-fade-in space-y-6">
        <div>
          <h1 className="page-title">Dashboard</h1>
          <p className="page-subtitle">Ringkasan aktivitas sistem rental hari ini</p>
        </div>

        {loading ? <LoadingSpinner className="py-16" /> : (
          <>
            {/* Hero */}
            <div className="rounded-2xl bg-gradient-to-r from-indigo-600 to-violet-500 text-white p-6 shadow-lg">
              <div className="flex items-center justify-between gap-4">
                <div>
                  <p className="text-sm text-indigo-100">Selamat datang kembali 👋</p>
                  <h2 className="text-2xl font-bold tracking-tight">{stats?.userName || 'Admin'}</h2>
                  <p className="text-sm text-indigo-200 mt-1">Kelola penyewaan alat Anda dengan mudah</p>
                </div>
                <div>
                  <button className="px-4 py-2 rounded-lg bg-white text-indigo-600 font-semibold shadow hover:scale-[1.02] transition-transform">Sewa Alat Sekarang →</button>
                </div>
              </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 xl:grid-cols-4 gap-4 mt-4">
              <StatsCard label="Total Booking" value={stats?.totalBooking} icon={<ShoppingCart />} color="indigo" sub={`${stats?.pendingBooking} menunggu konfirmasi`} />
              <StatsCard label="Total Pengguna" value={stats?.totalUser} icon={<Users />} color="blue" />
              <StatsCard label="Alat Tersedia" value={`${stats?.alatTersedia}/${stats?.totalAlat}`} icon={<Wrench />} color="emerald" />
              <StatsCard label="Total Revenue" value={`Rp ${(stats?.revenue || 0).toLocaleString('id-ID')}`} icon={<TrendingUp />} color="violet" sub={`${stats?.pendingPay} pembayaran pending`} />
            </div>

            {/* Alerts */}
            {(stats?.pendingBooking > 0 || stats?.pendingPay > 0) && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {stats.pendingBooking > 0 && (
                  <Alert
                    color="amber"
                    icon={<Clock className="h-5 w-5 text-amber-600" />}
                    title={`${stats.pendingBooking} Booking Menunggu Konfirmasi`}
                    desc="Perlu diproses segera"
                    link="/admin/bookings"
                  />
                )}
                {stats.pendingPay > 0 && (
                  <Alert
                    color="blue"
                    icon={<CreditCard className="h-5 w-5 text-blue-600" />}
                    title={`${stats.pendingPay} Pembayaran Menunggu Verifikasi`}
                    desc="Cek bukti transfer pelanggan"
                    link="/admin/pembayaran"
                  />
                )}
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              {/* Recent Bookings */}
              <div className="card">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="font-bold text-gray-900">Booking Terbaru</h2>
                  <Link to="/admin/bookings" className="text-xs font-semibold text-indigo-600 hover:underline flex items-center gap-1">
                    Semua <ArrowRight className="h-3 w-3" />
                  </Link>
                </div>
                <div className="space-y-1">
                  {recentBookings.length === 0 ? (
                    <p className="text-sm text-gray-400 text-center py-6">Belum ada data</p>
                  ) : recentBookings.map(b => (
                    <div key={b.id} className="flex items-center justify-between py-2.5 px-3 rounded-xl hover:bg-slate-50 transition-colors">
                      <div className="min-w-0">
                        <p className="text-sm font-semibold text-gray-900 truncate">{b.kode_booking}</p>
                        <p className="text-xs text-gray-500">{b.user?.nama}</p>
                      </div>
                      <div className="flex items-center gap-2 flex-shrink-0 ml-2">
                        <span className={`badge-${b.status}`}>{b.status}</span>
                        <p className="text-xs font-medium text-gray-700 hidden sm:block">Rp {Number(b.total_harga).toLocaleString('id-ID')}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Pending Payments */}
              <div className="card">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="font-bold text-gray-900">Pembayaran Pending</h2>
                  <Link to="/admin/pembayaran" className="text-xs font-semibold text-indigo-600 hover:underline flex items-center gap-1">
                    Semua <ArrowRight className="h-3 w-3" />
                  </Link>
                </div>
                <div className="space-y-1">
                  {pendingPay.length === 0 ? (
                    <div className="text-center py-6">
                      <CheckCircle className="h-8 w-8 text-emerald-400 mx-auto mb-2" />
                      <p className="text-sm text-gray-400">Semua pembayaran selesai</p>
                    </div>
                  ) : pendingPay.map(p => (
                    <div key={p.id} className="flex items-center justify-between py-2.5 px-3 rounded-xl hover:bg-slate-50 transition-colors">
                      <div className="min-w-0">
                        <p className="text-sm font-semibold text-gray-900 truncate">{p.booking?.kode_booking}</p>
                        <p className="text-xs text-gray-500">{p.booking?.user?.nama}</p>
                      </div>
                      <p className="text-sm font-bold text-gray-900 flex-shrink-0 ml-2">Rp {Number(p.jumlah).toLocaleString('id-ID')}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </AppLayout>
  );
}

function Alert({ color, icon, title, desc, link }) {
  const c = {
    amber: 'bg-amber-50 border-amber-200',
    blue:  'bg-blue-50 border-blue-200',
  };
  return (
    <div className={`${c[color]} border rounded-2xl p-4 flex items-center gap-3`}>
      <div className="flex-shrink-0 w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-sm">{icon}</div>
      <div className="flex-1 min-w-0">
        <p className="font-semibold text-gray-900 text-sm">{title}</p>
        <p className="text-xs text-gray-500 mt-0.5">{desc}</p>
      </div>
      <Link to={link} className="flex-shrink-0 btn-ghost text-xs font-semibold text-indigo-600 px-3 py-1.5">
        Lihat <ArrowRight className="h-3 w-3" />
      </Link>
    </div>
  );
}

