import { useState, useEffect, useRef } from 'react';
import AppLayout from '../../components/layout/AppLayout';
import api from '../../lib/api';
import Modal from '../../components/common/Modal';
import Pagination from '../../components/common/Pagination';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { useNavigate } from 'react-router-dom';
import { Search, ShoppingCart, Eye, ChevronDown, Download, Plus } from 'lucide-react';
import toast from 'react-hot-toast';

const ALL_STATUS = ['', 'pending', 'dikonfirmasi', 'permohonan_pembatalan', 'disewa', 'selesai', 'dibatalkan'];
const TRANSITIONS = {
  pending:                 ['dikonfirmasi', 'dibatalkan'],
  dikonfirmasi:            ['disewa', 'dibatalkan'],
  permohonan_pembatalan:   ['dikonfirmasi', 'dibatalkan'],
  disewa:                  ['selesai'],
  selesai: [], dibatalkan: [],
};

export default function BookingAdminPage() {
  const navigate = useNavigate();
  const [data, setData]             = useState([]);
  const [pagination, setPagination] = useState(null);
  const [loading, setLoading]       = useState(true);
  const [page, setPage]             = useState(1);
  const [search, setSearch]         = useState('');
  const [filterStatus, setFilter]   = useState('');
  const [detail, setDetail]         = useState({ open: false, item: null });
  const [confirm, setConfirm]       = useState({ open: false, item: null, status: '', reason: '' });
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => { fetchData(); }, [page, search, filterStatus]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const p = new URLSearchParams({ page, size: 10 });
      if (search) p.set('search', search);
      if (filterStatus) p.set('status', filterStatus);
      const res = await api.get(`/bookings?${p}`);
      setData(res.data.data);
      setPagination(res.data.pagination);
    } catch {}
    setLoading(false);
  };

  const handleStatusChange = async () => {
    setSubmitting(true);
    try {
      await api.patch(`/bookings/${confirm.item.id}/status`, {
        status: confirm.status,
      });
      toast.success(`Status diubah → ${confirm.status}`);
      setConfirm({ open: false, item: null, status: '', reason: '' });
      fetchData();
    } catch (err) { toast.error(err.response?.data?.message || 'Gagal'); }
    setSubmitting(false);
  };

  const openDetail = async (id) => {
    try { const r = await api.get(`/bookings/${id}`); setDetail({ open: true, item: r.data.data }); } catch {}
  };

  return (
    <AppLayout title="Data Booking">
      <div className="animate-fade-in space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="page-title">Manajemen Booking</h1>
            <p className="page-subtitle">Monitor dan kelola semua transaksi booking rental</p>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => navigate('/alat')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold text-sm rounded-xl shadow-sm transition">
              <Plus className="h-4 w-4" /> Buat Booking Baru
            </button>
            <button onClick={() => downloadExport('/bookings/export/excel', `bookings_${Date.now()}.xlsx`)} className="btn-ghost"><Download className="h-4 w-4" /> XLSX</button>
            <button onClick={() => downloadExport('/bookings/export/pdf', `bookings_${Date.now()}.pdf`)} className="btn-ghost"><Download className="h-4 w-4" /> PDF</button>
          </div>
        </div>

        <div className="card p-0 overflow-hidden">
          <div className="flex flex-col sm:flex-row gap-3 p-4 border-b border-gray-100">
            <div className="relative flex-1">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <input className="input-field pl-10" placeholder="Cari kode booking..." value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} />
            </div>
            <select className="input-field sm:w-44" value={filterStatus} onChange={e => { setFilter(e.target.value); setPage(1); }}>
              {ALL_STATUS.map(s => <option key={s} value={s}>{s || 'Semua Status'}</option>)}
            </select>
          </div>

          {loading ? <LoadingSpinner className="py-12" /> : (
            data.length === 0
              ? <EmptyState icon={<ShoppingCart />} text="Belum ada data booking" />
              : (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b border-gray-100 bg-slate-50">
                        <th className="table-header">Kode</th>
                        <th className="table-header">Customer</th>
                        <th className="table-header">Periode</th>
                        <th className="table-header">Total</th>
                        <th className="table-header">Status</th>
                        <th className="table-header text-right">Aksi</th>
                      </tr>
                    </thead>
                    <tbody>
                      {data.map(item => (
                        <tr key={item.id} className="table-row">
                          <td className="table-cell font-semibold text-gray-900">{item.kode_booking}</td>
                          <td className="table-cell text-gray-600">{item.user?.nama}</td>
                          <td className="table-cell text-gray-500 text-xs">
                            {new Date(item.tanggal_mulai).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })} –{' '}
                            {new Date(item.tanggal_selesai).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}
                          </td>
                          <td className="table-cell font-semibold">Rp {Number(item.total_harga).toLocaleString('id-ID')}</td>
                          <td className="table-cell"><span className={`badge-${item.status}`}>{item.status}</span></td>
                          <td className="table-cell text-right">
                            <div className="flex items-center justify-end gap-1.5">
                              <button onClick={() => openDetail(item.id)} className="btn-ghost p-2 text-gray-500" title="Lihat Detail / Formulir"><Eye className="h-4 w-4" /></button>
                              {['pending', 'dikonfirmasi', 'permohonan_pembatalan'].includes(item.status) && (
                                <button
                                  onClick={() => setConfirm({ open: true, item, status: 'dibatalkan', reason: '' })}
                                  className="px-2.5 py-1 text-xs font-bold bg-red-50 text-red-600 hover:bg-red-100 rounded-lg transition"
                                  title="Batalkan Booking"
                                >
                                  Batalkan
                                </button>
                              )}
                              {TRANSITIONS[item.status]?.length > 0 && (
                                <StatusDropdown
                                  options={TRANSITIONS[item.status]}
                                  onSelect={s => setConfirm({ open: true, item, status: s, reason: '' })}
                                />
                              )}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )
          )}
          <div className="px-4 pb-4"><Pagination pagination={pagination} onPageChange={setPage} /></div>
        </div>

        {/* Detail */}
        <Modal isOpen={detail.open} onClose={() => setDetail({ open: false, item: null })} title="Detail Booking" size="lg">
          {detail.item && <BookingDetailView booking={detail.item} />}
        </Modal>

        {/* Confirm status */}
        <Modal isOpen={confirm.open} onClose={() => setConfirm({ open: false, item: null, status: '' })} title="Konfirmasi Perubahan Status" size="sm">
          <div className="text-center py-2">
            <p className="text-gray-700 mb-2 text-sm">Ubah status <strong>{confirm.item?.kode_booking}</strong> menjadi:</p>
            <span className={`badge-${confirm.status} text-sm px-4 py-1.5`}>{confirm.status}</span>
          <div className="flex gap-3 mt-6">
            <button onClick={() => setConfirm({ open: false, item: null, status: '', reason: '' })} className="btn-secondary flex-1">Batal</button>
            <button onClick={handleStatusChange} disabled={submitting} className="btn-primary flex-1">
              {submitting ? 'Memproses...' : 'Ya, Ubah'}
            </button>
          </div>
          </div>
        </Modal>
      </div>
    </AppLayout>
  );
}

const downloadExport = async (path, filename) => {
  try {
    const res = await api.get(path, { responseType: 'blob' });
    const blob = new Blob([res.data], { type: res.headers['content-type'] });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(link.href);
  } catch (err) { /* ignore */ }
};

function StatusDropdown({ options, onSelect }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);
  return (
    <div className="relative" ref={ref}>
      <button onClick={() => setOpen(o => !o)} className="flex items-center gap-1 px-3 py-1.5 bg-indigo-50 text-indigo-700 rounded-lg text-xs font-semibold hover:bg-indigo-100 transition-colors">
        Ubah <ChevronDown className={`h-3 w-3 transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && (
        <div className="absolute right-0 top-9 bg-white rounded-xl shadow-lg border border-gray-100 py-1 min-w-[140px] z-20 animate-scale-in">
          {options.map(s => (
            <button key={s} onClick={() => { onSelect(s); setOpen(false); }}
              className="w-full text-left px-4 py-2 text-sm hover:bg-indigo-50 hover:text-indigo-700 transition-colors capitalize">
              {s}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function BookingDetailView({ booking }) {
  const durasi = Math.max(1, (new Date(booking.tanggal_selesai) - new Date(booking.tanggal_mulai)) / (1000 * 60 * 60 * 24) + 1);
  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 gap-3 text-sm">
        {[
          ['Kode Booking', booking.kode_booking, true],
          ['Status Booking', <span className={`badge-${booking.status}`}>{booking.status}</span>],
          ['Customer', booking.user?.nama],
          ['No HP / Email', `${booking.user?.no_hp || '-'} • ${booking.user?.email || '-'}`],
          ['Opsi Pembayaran', (booking.opsi_pembayaran || 'dp').toUpperCase().replace('_', ' ')],
          ['Status Pembayaran', (booking.status_pembayaran || 'belum_bayar').toUpperCase().replace('_', ' ')],
          ['DP Dibayar', `Rp ${Number(booking.jumlah_dp || 0).toLocaleString('id-ID')}`],
          ['Sisa Tagihan', `Rp ${Number(booking.sisa_pembayaran || 0).toLocaleString('id-ID')}`],
        ].map(([l, v, bold]) => (
          <div key={l} className="bg-gray-50 p-2.5 rounded-xl">
            <p className="text-[11px] text-gray-500 mb-0.5">{l}</p>
            <div className={bold ? 'font-bold text-gray-900' : 'font-semibold text-gray-800'}>{v}</div>
          </div>
        ))}
      </div>
      {booking.details?.length > 0 && (
        <div>
          <p className="text-sm font-semibold text-gray-700 mb-2">Item Alat & Jadwal Per-Alat</p>
          <div className="space-y-2">
            {booking.details.map(d => {
              const itemMulai = d.tanggal_mulai ? new Date(d.tanggal_mulai).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' }) : null;
              const itemSelesai = d.tanggal_selesai ? new Date(d.tanggal_selesai).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }) : null;
              const itemDurasi = d.tanggal_mulai && d.tanggal_selesai ? Math.max(1, (new Date(d.tanggal_selesai) - new Date(d.tanggal_mulai)) / 86400000 + 1) : durasi;

              return (
                <div key={d.id} className="p-3 bg-slate-50 rounded-xl space-y-1">
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-semibold text-gray-900">{d.alat?.nama_alat}</p>
                    <p className="font-bold text-indigo-600 text-sm">Rp {Number(d.subtotal).toLocaleString('id-ID')}</p>
                  </div>
                  {itemMulai && itemSelesai && (
                    <p className="text-xs font-semibold text-indigo-600">
                      📅 {itemMulai} – {itemSelesai} ({itemDurasi} hari)
                    </p>
                  )}
                  <p className="text-xs text-gray-500">{d.qty} unit × Rp {Number(d.harga).toLocaleString('id-ID')}/hari × {itemDurasi} hari</p>
                </div>
              );
            })}
          </div>
          <div className="flex justify-between items-center mt-3 pt-3 border-t border-gray-100">
            <p className="font-semibold text-gray-700">Total Keseluruhan</p>
            <p className="text-lg font-bold text-indigo-600">Rp {Number(booking.total_harga).toLocaleString('id-ID')}</p>
          </div>
        </div>
      )}
      {booking.catatan && (
        <div className="bg-amber-50 rounded-xl p-3 border border-amber-100">
          <p className="text-xs text-amber-700 font-semibold mb-1">Catatan Customer</p>
          <p className="text-sm text-gray-700">{booking.catatan}</p>
        </div>
      )}
      {booking.alasan_pembatalan && (
        <div className="bg-red-50 rounded-xl p-3 border border-red-100">
          <p className="text-xs text-red-700 font-semibold mb-1">Alasan Pembatalan</p>
          <p className="text-sm text-gray-700">{booking.alasan_pembatalan}</p>
        </div>
      )}
    </div>
  );
}

function EmptyState({ icon, text }) {
  return (
    <div className="text-center py-14">
      <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center mx-auto mb-3">
        <div className="h-7 w-7 text-gray-400">{icon}</div>
      </div>
      <p className="text-gray-500 font-medium">{text}</p>
    </div>
  );
}

