import { useState, useEffect } from 'react';
import AppLayout from '../../components/layout/AppLayout';
import api from '../../lib/api';
import Modal from '../../components/common/Modal';
import Pagination from '../../components/common/Pagination';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { Edit2, Search, Users, UserPlus, Phone, MapPin, Mail, Eye, ShoppingCart, Calendar, ShieldCheck, FileText, ExternalLink } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';

export default function CustomerAdminPage() {
  const navigate = useNavigate();
  const [data, setData]             = useState([]);
  const [pagination, setPagination] = useState(null);
  const [loading, setLoading]       = useState(true);
  const [page, setPage]             = useState(1);
  const [search, setSearch]         = useState('');
  const [modal, setModal]           = useState({ open: false, item: null });
  const [detailModal, setDetailModal] = useState({ open: false, item: null, loading: false });

  const [form, setForm]             = useState({ nama: '', email: '', password: '', no_hp: '', nik: '', alamat: '', kontak_darurat_nama: '', kontak_darurat_hp: '' });
  const [submitting, setSubmitting] = useState(false);
  const [customerRoleId, setCustomerRoleId] = useState(null);

  useEffect(() => {
    api.get('/roles').then(r => {
      const roles = r.data.data || [];
      const custRole = roles.find(role => role.nama_role === 'customer');
      if (custRole) setCustomerRoleId(custRole.id);
      else setCustomerRoleId(2);
    }).catch(() => setCustomerRoleId(2));
  }, []);

  useEffect(() => {
    if (customerRoleId) fetchData();
  }, [page, search, customerRoleId]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const p = new URLSearchParams({ page, size: 10, role_id: customerRoleId });
      if (search) p.set('search', search);
      const res = await api.get(`/users?${p}`);
      setData(res.data.data || []);
      setPagination(res.data.pagination);
    } catch (err) {
      toast.error('Gagal mengambil data customer');
    }
    setLoading(false);
  };

  const openCreate = () => {
    setForm({ nama: '', email: '', password: '', no_hp: '', nik: '', alamat: '', kontak_darurat_nama: '', kontak_darurat_hp: '' });
    setModal({ open: true, item: null });
  };

  const openEdit = (item) => {
    setForm({
      nama: item.nama,
      email: item.email,
      password: '',
      no_hp: item.no_hp || '',
      nik: item.nik || '',
      alamat: item.alamat || '',
      kontak_darurat_nama: item.kontak_darurat_nama || '',
      kontak_darurat_hp: item.kontak_darurat_hp || '',
    });
    setModal({ open: true, item });
  };

  const openDetail = async (id) => {
    setDetailModal({ open: true, item: null, loading: true });
    try {
      const res = await api.get(`/users/${id}`);
      setDetailModal({ open: true, item: res.data.data, loading: false });
    } catch {
      toast.error('Gagal memuat detail customer');
      setDetailModal({ open: false, item: null, loading: false });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      const fd = new FormData();
      fd.append('nama', form.nama);
      fd.append('email', form.email);
      if (form.password) fd.append('password', form.password);
      else if (!modal.item) fd.append('password', 'customer123');
      fd.append('no_hp', form.no_hp);
      fd.append('nik', form.nik);
      fd.append('alamat', form.alamat);
      fd.append('kontak_darurat_nama', form.kontak_darurat_nama);
      fd.append('kontak_darurat_hp', form.kontak_darurat_hp);
      fd.append('role_id', customerRoleId);
      fd.append('status', 'aktif');

      if (modal.item) {
        await api.put(`/users/${modal.item.id}`, fd);
        toast.success('Data Customer diperbarui');
      } else {
        await api.post('/users', fd);
        toast.success('Customer baru berhasil ditambahkan');
      }
      setModal({ open: false, item: null });
      fetchData();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Gagal menyimpan data customer');
    }
    setSubmitting(false);
  };

  const set = k => e => setForm(f => ({ ...f, [k]: e.target.value }));

  return (
    <AppLayout title="Kelola Customer">
      <div className="space-y-6">
        {/* Header Bar */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
          <div>
            <h1 className="text-xl font-bold text-gray-900 flex items-center gap-2">
              <Users className="h-6 w-6 text-indigo-600" />
              Kelola & Riwayat Customer
            </h1>
            <p className="text-sm text-gray-500 mt-1">
              Customer otomatis tercatat saat booking dibuat. Klik detail untuk melihat profil & riwayat sewa.
            </p>
          </div>
          <button
            onClick={openCreate}
            className="flex items-center justify-center gap-2 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-sm font-semibold shadow-sm shadow-indigo-200 transition"
          >
            <UserPlus className="h-4 w-4" />
            Tambah Customer Manual
          </button>
        </div>

        {/* Search */}
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
          <div className="relative max-w-md">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <input
              type="text"
              placeholder="Cari nama, email, NIK customer..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
            />
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
          {loading ? (
            <div className="py-12"><LoadingSpinner /></div>
          ) : data.length === 0 ? (
            <div className="py-12 text-center text-gray-500">Belum ada data customer terdaftar. Customer akan otomatis muncul di sini setelah booking dilakukan.</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm text-gray-600">
                <thead className="bg-gray-50 text-gray-700 font-semibold border-b border-gray-100">
                  <tr>
                    <th className="px-6 py-3.5">Nama Customer & NIK</th>
                    <th className="px-6 py-3.5">Kontak</th>
                    <th className="px-6 py-3.5">Total Booking</th>
                    <th className="px-6 py-3.5">Alamat</th>
                    <th className="px-6 py-3.5 text-right">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {data.map(item => (
                    <tr key={item.id} className="hover:bg-gray-50/50 transition">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-10 h-10 rounded-2xl bg-indigo-100 text-indigo-700 font-bold flex items-center justify-center text-sm flex-shrink-0">
                            {item.nama?.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <p className="font-bold text-gray-900">{item.nama}</p>
                            <p className="text-xs text-gray-500 font-mono">
                              NIK: {item.nik || 'Belum diisi'}
                            </p>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="space-y-1 text-xs">
                          <p className="font-medium text-gray-900 flex items-center gap-1">
                            <Phone className="h-3 w-3 text-indigo-600" /> {item.no_hp || '-'}
                          </p>
                          <p className="text-gray-500 flex items-center gap-1">
                            <Mail className="h-3 w-3 text-gray-400" /> {item.email}
                          </p>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-700 rounded-xl text-xs font-bold">
                          <ShoppingCart className="h-3.5 w-3.5" />
                          {item.bookings?.length || 0} Transaksi
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <p className="text-xs text-gray-600 max-w-xs truncate flex items-center gap-1">
                          <MapPin className="h-3 w-3 text-gray-400 flex-shrink-0" />
                          {item.alamat || '-'}
                        </p>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-1">
                          <button
                            onClick={() => openDetail(item.id)}
                            className="flex items-center gap-1 px-3 py-1.5 bg-indigo-50 text-indigo-700 hover:bg-indigo-100 rounded-xl text-xs font-bold transition"
                            title="Lihat Detail Customer & Riwayat Booking"
                          >
                            <Eye className="h-3.5 w-3.5" /> Detail
                          </button>
                          <button
                            onClick={() => openEdit(item)}
                            className="p-1.5 text-gray-400 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition"
                            title="Edit Data Customer"
                          >
                            <Edit2 className="h-4 w-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          {pagination && (
            <div className="p-4 border-t border-gray-100">
