        onClose={() => setDetailModal({ open: false, item: null, loading: false })}
        title="Profil & Riwayat Transaksi Customer"
        size="xl"
      >
        {detailModal.loading ? (
          <div className="py-12"><LoadingSpinner /></div>
        ) : detailModal.item ? (
          <div className="space-y-6">
            {/* Header Profile Card */}
            <div className="p-5 bg-gradient-to-r from-slate-900 to-indigo-950 rounded-3xl text-white flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div className="flex items-center gap-4">
