                </div>
                <div>
                  <h3 className="text-xl font-bold">{detailModal.item.nama}</h3>
                  <p className="text-xs text-indigo-200 font-mono mt-0.5">NIK: {detailModal.item.nik || 'Belum diisi'}</p>
