                </div>
              </div>
              <div className="text-right border-t sm:border-t-0 border-white/10 pt-3 sm:pt-0">
                <span className="text-xs text-indigo-200 block">Total Penyewaan</span>
                <span className="text-2xl font-black text-white">{detailModal.item.bookings?.length || 0} Kali</span>
              </div>
