import { useState, useEffect } from 'react';
import AppLayout from '../../components/layout/AppLayout';
import api from '../../lib/api';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import Modal from '../../components/common/Modal';
import {
  Calendar, ChevronLeft, ChevronRight, Search, Plus, Filter,
  Wrench, Camera, Cpu, Zap, HardHat, ShieldCheck, AlertTriangle,
  XCircle, Clock, User, CheckCircle2, ArrowRight, ExternalLink, RefreshCw, AlertCircle
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';

const NAMA_BULAN = [
  'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
  'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
];

export default function LogBookPage() {
  const navigate = useNavigate();
  const now = new Date();

  const [bulan, setBulan]       = useState(now.getMonth() + 1);
  const [tahun, setTahun]       = useState(now.getFullYear());
  const [search, setSearch]     = useState('');
  const [selKat, setSelKat]     = useState('');
  const [selStatus, setSelStatus] = useState(''); // '', 'tersedia', 'disewa', 'overbooking', 'maintenance', 'rusak'

  const [loading, setLoading]       = useState(true);
  const [logbook, setLogbook]       = useState(null);
  const [kategoriList, setKategoriList] = useState([]);

  // Detail Modals
  const [toolDetailModal, setToolDetailModal] = useState({ open: false, item: null });
  const [bookingDetailModal, setBookingDetailModal] = useState({ open: false, item: null });

  useEffect(() => {
    api.get('/kategori-alat?size=100').then(r => setKategoriList(r.data.data || [])).catch(() => {});
  }, []);

  useEffect(() => {
    fetchLogbook();
  }, [bulan, tahun]);

  const fetchLogbook = async () => {
    setLoading(true);
    try {
      const res = await api.get(`/bookings/logbook?bulan=${bulan}&tahun=${tahun}`);
      setLogbook(res.data.data);
    } catch {
      toast.error('Gagal mengambil data Gantt chart logbook');
    }
    setLoading(false);
  };

  const handleCurrentMonth = () => {
    setBulan(now.getMonth() + 1);
    setTahun(now.getFullYear());
  };

  const prevMonth = () => {
    if (bulan === 1) { setBulan(12); setTahun(t => t - 1); }
    else setBulan(b => b - 1);
  };

  const nextMonth = () => {
    if (bulan === 12) { setBulan(1); setTahun(t => t + 1); }
    else setBulan(b => b + 1);
  };

  const currentMonthName = NAMA_BULAN[bulan - 1];

  // Helper icon for category/name
  const getItemIcon = (name = '', cat = '') => {
    const s = (name + ' ' + cat).toLowerCase();
    if (s.includes('kamera') || s.includes('camera') || s.includes('dslr')) return <Camera className="h-4 w-4 text-indigo-500" />;
    if (s.includes('elektronik') || s.includes('proyektor') || s.includes('drone')) return <Cpu className="h-4 w-4 text-blue-500" />;
    if (s.includes('bor') || s.includes('listrik') || s.includes('genset') || s.includes('vibration')) return <Zap className="h-4 w-4 text-amber-500" />;
    if (s.includes('kemah') || s.includes('tenda') || s.includes('outdoor')) return <HardHat className="h-4 w-4 text-emerald-500" />;
    return <Wrench className="h-4 w-4 text-slate-500" />;
  };

  // Filter matrix items
  const filteredMatrix = (logbook?.matrix || []).filter(item => {
    const matchSearch = !search ||
      item.nama_alat.toLowerCase().includes(search.toLowerCase()) ||
      item.kode_alat.toLowerCase().includes(search.toLowerCase()) ||
      item.merek.toLowerCase().includes(search.toLowerCase());

    const matchKat = !selKat || String(item.kategori) === String(selKat);

    let matchStatus = true;
    if (selStatus === 'overbooking') matchStatus = item.is_overbooked;
    else if (selStatus === 'tersedia') matchStatus = !item.is_overbooked && item.status === 'tersedia' && item.kondisi === 'baik';
    else if (selStatus === 'disewa') matchStatus = item.lanes && item.lanes.length > 0;
    else if (selStatus === 'maintenance') matchStatus = item.kondisi === 'rusak_ringan';
    else if (selStatus === 'rusak') matchStatus = item.kondisi === 'rusak_berat';

    return matchSearch && matchKat && matchStatus;
  });

  return (
    <AppLayout title="Multi-Unit Rental Gantt Chart">
      <div className="space-y-6 animate-fade-in font-sans">

        {/* 3. BAGIAN KANAN ATAS & ATAS: CONTROL PANEL */}
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">

          {/* Header Bar */}
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 border-b border-gray-100 pb-5">
            <div>
              <div className="flex items-center gap-2">
                <span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl">
                  <Calendar className="h-5 w-5" />
                </span>
                <h1 className="text-xl font-black text-slate-900 tracking-tight">Multi-Unit Rental Gantt Chart</h1>
              </div>
              <p className="text-xs text-gray-500 mt-1">
                Visualisasi multi-unit & multiple rental simultan per-barang dengan deteksi Over Booking otomatis.
              </p>
            </div>

            {/* Kontrol Bulan & Tombol Aksi Kanan Atas */}
            <div className="flex flex-wrap items-center gap-2.5">

              {/* Selector [ ◀ ] 📅 Juli 2026 [ ▶ ] */}
              <div className="flex items-center bg-slate-900 text-white rounded-2xl p-1 shadow-md">
                <button
                  onClick={prevMonth}
                  className="p-2 hover:bg-slate-800 rounded-xl transition text-slate-300 hover:text-white"
                  title="Bulan Sebelumnya"
                >
                  <ChevronLeft className="h-4 w-4" />
                </button>

                <div className="px-3 text-xs font-black tracking-wide flex items-center gap-1.5 cursor-pointer">
                  <span>📅 {currentMonthName} {tahun}</span>
                </div>

                <button
                  onClick={nextMonth}
                  className="p-2 hover:bg-slate-800 rounded-xl transition text-slate-300 hover:text-white"
                  title="Bulan Berikutnya"
                >
                  <ChevronRight className="h-4 w-4" />
                </button>
              </div>

              {/* Month Picker Select */}
              <select
                value={bulan}
                onChange={e => setBulan(Number(e.target.value))}
                className="px-3 py-2 bg-gray-50 border border-gray-200 rounded-xl text-xs font-bold text-gray-800 focus:ring-2 focus:ring-indigo-500"
              >
                {NAMA_BULAN.map((m, i) => (
                  <option key={m} value={i + 1}>{m}</option>
                ))}
              </select>

              {/* Tombol Hari Ini */}
              <button
                onClick={handleCurrentMonth}
                className="px-3 py-2 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-xl text-xs font-bold transition flex items-center gap-1"
              >
                <RefreshCw className="h-3.5 w-3.5 text-indigo-600" /> Hari Ini
              </button>

              {/* Tombol Tambah Rental + */}
              <button
                onClick={() => navigate('/alat')}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-extrabold shadow-md shadow-indigo-200 transition flex items-center gap-1.5"
              >
                <Plus className="h-4 w-4" /> Tambah Rental +
              </button>
            </div>
          </div>

          {/* Search & Filter Bar */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div className="relative">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <input
                type="text"
                placeholder="Cari nama barang, kode..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-indigo-500 focus:bg-white"
              />
            </div>

            <div>
              <select
                value={selKat}
                onChange={e => setSelKat(e.target.value)}
                className="w-full px-3.5 py-2 bg-gray-50 border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-indigo-500 focus:bg-white"
              >
                <option value="">Semua Kategori</option>
                {kategoriList.map(k => (
                  <option key={k.id} value={k.nama_kategori}>{k.nama_kategori}</option>
                ))}
              </select>
            </div>

            <div>
              <select
                value={selStatus}
                onChange={e => setSelStatus(e.target.value)}
                className="w-full px-3.5 py-2 bg-gray-50 border border-gray-200 rounded-xl text-xs font-semibold focus:ring-2 focus:ring-indigo-500 focus:bg-white"
              >
                <option value="">Filter Status Barang (Semua)</option>
                <option value="overbooking">⚠️ Over Booking</option>
                <option value="disewa">🟦 Biru - Sedang Rental</option>
                <option value="tersedia">🟩 Hijau - Tersedia</option>
                <option value="maintenance">🟧 Orange - Maintenance</option>
                <option value="rusak">🟥 Merah - Rusak</option>
              </select>
            </div>
          </div>

          {/* Legend Indicators */}
          <div className="flex flex-wrap items-center justify-between gap-4 pt-1 text-[11px] font-semibold text-gray-600 border-t border-gray-100">
            <div className="flex flex-wrap items-center gap-4">
              <span className="font-bold text-gray-800">Status Warna:</span>
              <div className="flex items-center gap-1.5">
                <span className="w-3 h-3 rounded-full bg-emerald-500 shadow-sm"></span>
                <span>Hijau = Tersedia</span>
              </div>
              <div className="flex items-center gap-1.5">
                <span className="w-3 h-3 rounded-full bg-blue-600 shadow-sm"></span>
                <span>Biru = Sedang Rental</span>
              </div>
              <div className="flex items-center gap-1.5">
                <span className="w-3 h-3 rounded-full bg-amber-500 shadow-sm"></span>
                <span>Orange = Maintenance</span>
              </div>
              <div className="flex items-center gap-1.5">
                <span className="w-3 h-3 rounded-full bg-rose-600 shadow-sm"></span>
                <span>Merah = Rusak</span>
              </div>
              <div className="flex items-center gap-1.5">
                <span className="px-2 py-0.5 bg-red-100 text-red-700 font-extrabold rounded-md border border-red-300">
