            </p>

            <div className="grid grid-cols-2 gap-6 pt-4 border-t border-gray-200">
              {/* TTD Customer */}
              <div className="text-center space-y-2">
                <p className="text-xs font-bold text-slate-900">Penyewa (Customer)</p>
                <div className="h-28 border border-gray-300 rounded-xl flex items-center justify-center p-2 bg-slate-50">
                  {booking.tanda_tangan_customer ? (
                    <img src={booking.tanda_tangan_customer} alt="Tanda Tangan Customer" className="max-h-full object-contain" />
