                    <span className="text-xs text-gray-400 italic">[ Belum Ada Tanda Tangan ]</span>
                  )}
                </div>
                <p className="text-xs font-semibold text-slate-800 uppercase font-mono">( {booking.user?.nama || 'Nama Customer'} )</p>
              </div>

              {/* TTD Admin */}
              <div className="text-center space-y-2">
                <p className="text-xs font-bold text-slate-900">Petugas Rental (Admin)</p>
                <div className="h-28 border border-gray-300 rounded-xl flex items-center justify-center p-2 bg-slate-50">
                  {booking.tanda_tangan_admin ? (
                    <img src={booking.tanda_tangan_admin} alt="Tanda Tangan Admin" className="max-h-full object-contain" />
                  ) : (
                    <span className="text-xs text-gray-400 italic">[ Tanda Tangan Petugas ]</span>
                  )}
                </div>
                <p className="text-xs font-semibold text-slate-800 uppercase font-mono">( Staff Admin / RentalHub )</p>
              </div>
            </div>
          </div>

        </div>

        {/* Actions Button */}
        {(booking.status === 'pending' || booking.status === 'dikonfirmasi') && (
          <div className="print:hidden">
            <button
              type="button"
              onClick={() => setCancelModal({ open: true, reason: '', type: 'cancel' })}
              className="btn-danger w-full justify-center py-3"
            >
              Batalkan Booking Ini
            </button>
          </div>
        )}

        <Modal isOpen={cancelModal.open} onClose={() => setCancelModal({ open: false, reason: '', type: '' })} title="Konfirmasi Batalkan Booking">
          <div className="space-y-4 text-center py-2">
            <p className="text-sm text-gray-700">Apakah Anda yakin ingin membatalkan transaksi booking <strong>{booking.kode_booking}</strong>?</p>
            <div className="flex gap-3 pt-2">
              <button onClick={() => setCancelModal({ open: false, reason: '', type: '' })} className="btn-secondary flex-1">Tidak, Kembali</button>
              <button
                onClick={async () => {
                  setSubmittingCancel(true);
                  try {
                    await api.patch(`/bookings/${booking.id}/status`, { status: 'dibatalkan' });
                    toast.success('Booking berhasil dibatalkan');
                    setCancelModal({ open: false, reason: '', type: '' });
                    fetchBooking();
                  } catch (err) {
                    toast.error(err.response?.data?.message || 'Gagal membatalkan');
                  }
                  setSubmittingCancel(false);
                }}
                className="btn-danger flex-1"
                disabled={submittingCancel}
              >
                {submittingCancel ? 'Memproses...' : 'Ya, Batalkan'}
              </button>
            </div>
          </div>
        </Modal>
      </div>
    </AppLayout>
  );
}

