import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import AppLayout from '../../components/layout/AppLayout';
import api from '../../lib/api';
import Pagination from '../../components/common/Pagination';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { Search, ShoppingCart, ChevronRight, Plus } from 'lucide-react';

const STATUS_LIST = ['', 'pending', 'dikonfirmasi', 'permohonan_pembatalan', 'disewa', 'selesai', 'dibatalkan'];

export default function BookingsPage() {
  const [bookings, setBookings]     = useState([]);
  const [pagination, setPagination] = useState(null);
  const [loading, setLoading]       = useState(true);
  const [search, setSearch]         = useState('');
  const [status, setStatus]         = useState('');
  const [page, setPage]             = useState(1);

  useEffect(() => { fetchBookings(); }, [search, status, page]);

  const fetchBookings = async () => {
    setLoading(true);
    try {
      const p = new URLSearchParams({ page, size: 10 });
      if (search) p.set('search', search);
      if (status) p.set('status', status);
      const res = await api.get(`/bookings?${p}`);
      setBookings(res.data.data);
      setPagination(res.data.pagination);
    } catch {}
    setLoading(false);
  };

  return (
    <AppLayout>
      <div className="animate-fade-in space-y-6">
        <div className="page-header">
          <div>
            <h1 className="page-title">Booking Saya</h1>
            <p className="page-subtitle">Kelola semua transaksi penyewaan alat</p>
          </div>
          <Link to="/alat" className="btn-primary"><Plus className="h-4 w-4" /> Booking Baru</Link>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <input className="input-field pl-10" placeholder="Cari kode booking..." value={search}
              onChange={e => { setSearch(e.target.value); setPage(1); }} />
          </div>
          <select className="input-field sm:w-44" value={status} onChange={e => { setStatus(e.target.value); setPage(1); }}>
            {STATUS_LIST.map(s => <option key={s} value={s}>{s || 'Semua Status'}</option>)}
          </select>
        </div>

        {loading ? <LoadingSpinner className="py-16" /> : (
          <>
            {bookings.length === 0 ? (
              <div className="card text-center py-14">
                <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
                  <ShoppingCart className="h-7 w-7 text-gray-400" />
                </div>
                <p className="text-gray-600 font-semibold">Belum ada booking</p>
                <p className="text-gray-400 text-sm mt-1 mb-4">Mulai sewa alat untuk melihat riwayat di sini</p>
                <Link to="/alat" className="btn-primary inline-flex">
                  <ShoppingCart className="h-4 w-4" /> Sewa Sekarang
                </Link>
              </div>
            ) : (
              <div className="space-y-3">
                {bookings.map(b => (
                  <Link key={b.id} to={`/bookings/${b.id}`}
                    className="card-hover flex items-center gap-4 block">
                    <div className="w-11 h-11 rounded-xl bg-indigo-50 flex items-center justify-center flex-shrink-0">
                      <ShoppingCart className="h-5 w-5 text-indigo-600" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <p className="font-bold text-gray-900">{b.kode_booking}</p>
                        <span className={`badge-${b.status}`}>{b.status}</span>
                      </div>
                      <p className="text-xs text-gray-500 mt-0.5">
                        {new Date(b.tanggal_mulai).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })} —{' '}
                        {new Date(b.tanggal_selesai).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}
                        {' · '}{b.details?.length || 0} item
                      </p>
                    </div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <div className="text-right hidden sm:block">
                        <p className="font-bold text-gray-900 text-sm">Rp {Number(b.total_harga).toLocaleString('id-ID')}</p>
                        <p className="text-xs text-gray-400">{new Date(b.tanggal_booking).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })}</p>
                      </div>
                      <ChevronRight className="h-4 w-4 text-gray-300" />
                    </div>
                  </Link>
                ))}
              </div>
            )}
            <Pagination pagination={pagination} onPageChange={setPage} />
          </>
        )}
      </div>
    </AppLayout>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import AppLayout from '../../components/layout/AppLayout';
import api, { IMAGE_BASE } from '../../lib/api';
import { useAuth } from '../../contexts/AuthContext';
import SignaturePad from '../../components/common/SignaturePad';
import {
  Calendar, FileText, CheckCircle, ArrowLeft,
  Package, Calculator, AlertTriangle, XCircle, RefreshCw, UserCheck, CreditCard, Clock, ShieldCheck, FileCheck
} from 'lucide-react';
import ConfirmDialog from '../../components/common/ConfirmDialog';
import toast from 'react-hot-toast';

const today = new Date().toISOString().split('T')[0];
const tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];
const toLocal = (s) => { const [y,m,d] = s.split('-').map(Number); return new Date(y,m-1,d); };

export default function CreateBookingPage() {
  const { state }  = useLocation();
  const navigate   = useNavigate();
  const { isAdmin, user: currentUser } = useAuth();

  const itemsInit = (state?.items || []).map(item => ({
    ...item,
    tanggal_mulai: item.tanggal_mulai || today,
    tanggal_selesai: item.tanggal_selesai || tomorrow,
    kelengkapan: 'Unit utama, tas & kabel charger',
  }));
  const alatData  = state?.alat || [];

  const [items, setItems] = useState(itemsInit);
  const [catatan, setCatatan] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [customers, setCustomers] = useState([]);
  const [opsiPembayaran, setOpsiPembayaran] = useState('dp'); // 'dp', 'bayar_setelah_selesai', 'lunas_awal'
  const [persenDp, setPersenDp] = useState(30);

  // Form Fields Tambahan (Formulir Penyewaan)
  const [customerForm, setCustomerForm] = useState({
    nama: '',
    nik: '',
    no_hp: '',
    email: '',
    alamat: '',
    kontak_darurat_nama: '',
    kontak_darurat_hp: '',
  });

  const [jamMulai, setJamMulai] = useState('09:00');
  const [jamSelesai, setJamSelesai] = useState('17:00');
  const [uangJaminan, setUangJaminan] = useState(100000);
  const [jenisJaminan, setJenisJaminan] = useState('KTP Asli');

  // Digital Signatures
  const [ttdCustomer, setTtdCustomer] = useState('');
  const [ttdAdmin, setTtdAdmin] = useState('');

  const [loading, setLoading]   = useState(false);
  const [checking, setChecking] = useState(false);
  const [konflik, setKonflik]   = useState({});

  const getAlat = (id) => alatData.find(a => a.id === id);

  // Load customer list if Admin
  useEffect(() => {
    if (isAdmin) {
      api.get('/roles').then(res => {
        const custRole = (res.data.data || []).find(r => r.nama_role === 'customer');
        const roleId = custRole ? custRole.id : 2;
        return api.get(`/users?size=100&role_id=${roleId}`);
      }).then(res => {
        setCustomers(res.data.data || []);
      }).catch(() => {});
    }
  }, [isAdmin]);

  // When selected Customer changes, fill Customer Form
  useEffect(() => {
    if (selectedCustomerId) {
      const cust = customers.find(c => String(c.id) === String(selectedCustomerId));
      if (cust) {
        setCustomerForm({
          nama: cust.nama || '',
          nik: cust.nik || '',
          no_hp: cust.no_hp || '',
          email: cust.email || '',
          alamat: cust.alamat || '',
          kontak_darurat_nama: cust.kontak_darurat_nama || '',
          kontak_darurat_hp: cust.kontak_darurat_hp || '',
        });
      }
    }
  }, [selectedCustomerId, customers]);

  /* ── Hitung durasi & subtotal per item ── */
  const getItemDurasi = (item) => {
    if (!item.tanggal_mulai || !item.tanggal_selesai) return 0;
    const d = (new Date(item.tanggal_selesai) - new Date(item.tanggal_mulai)) / 86400000 + 1;
    return d > 0 ? d : 0;
  };

  const getItemSubtotal = (item) => {
    const alat = getAlat(item.alat_id);
    const d = getItemDurasi(item);
    return alat && d > 0 ? Number(alat.harga_sewa) * item.qty * d : 0;
  };

  const getTotalHarga = () => {
    return items.reduce((sum, item) => sum + getItemSubtotal(item), 0);
  };

  const getJumlahDp = () => {
    const total = getTotalHarga();
    if (opsiPembayaran === 'bayar_setelah_selesai' || opsiPembayaran === 'batal_booking') return 0;
    if (opsiPembayaran === 'lunas_awal') return total;
    return Math.round((total * persenDp) / 100);
  };

  const getSisaPembayaran = () => {
    if (opsiPembayaran === 'batal_booking') return 0;
    return Math.max(0, getTotalHarga() - getJumlahDp());
  };

  /* ── Cek ketersediaan alat ── */
  const cekKetersediaan = useCallback(async () => {
    if (items.length === 0) { setKonflik({}); return; }

    setChecking(true);
    try {
      const newKonflik = {};

      for (const item of items) {
        if (!item.tanggal_mulai || !item.tanggal_selesai || getItemDurasi(item) <= 0) continue;
        const alat = getAlat(item.alat_id);
        if (!alat) continue;

        const res = await api.get(
          `/bookings/kalender?tanggal_mulai=${item.tanggal_mulai}&tanggal_selesai=${item.tanggal_selesai}`
        );
        const bookings = res.data.data || [];
        const startDt = toLocal(item.tanggal_mulai);
        const endDt = toLocal(item.tanggal_selesai);

        const overlap = bookings.filter(b =>
          b.details?.some(d => d.alat_id === item.alat_id)
        );

        let minSisa = alat.stok;
        const tanggalHabis = [];

        let cur = new Date(startDt);
        while (cur <= endDt) {
          const qtyTerpakai = overlap
            .filter(b => toLocal(b.tanggal_mulai) <= cur && toLocal(b.tanggal_selesai) >= cur)
            .reduce((s, b) => {
              const det = b.details?.find(d => d.alat_id === item.alat_id);
              return s + (det?.qty || 0);
            }, 0);

          const sisa = alat.stok - qtyTerpakai;
          if (sisa < item.qty) {
            tanggalHabis.push(new Date(cur));
            if (sisa < minSisa) minSisa = sisa;
          }
          cur.setDate(cur.getDate() + 1);
        }

        if (tanggalHabis.length > 0) {
          newKonflik[item.alat_id] = {
            nama: alat.nama_alat,
            dibutuhkan: item.qty,
            minSisa: Math.max(0, minSisa),
            tanggalHabis,
          };
        }
      }
      setKonflik(newKonflik);
    } catch {
      setKonflik({});
    }
    setChecking(false);
  }, [items, alatData]);

  useEffect(() => {
    const t = setTimeout(() => {
      cekKetersediaan();
    }, 400);
    return () => clearTimeout(t);
  }, [items, cekKetersediaan]);

  useEffect(() => {
    if (items.length === 0) {
      navigate('/alat');
    }
  }, [items, navigate]);

  const [confirmOpen, setConfirmOpen] = useState(false);
  const [confirmAlat, setConfirmAlat] = useState(null);
  const [removingId, setRemovingId] = useState(null);

  const handleDeleteClick = (alatId) => {
    setConfirmAlat(alatId);
    setConfirmOpen(true);
  };

  const removeItem = (alatId) => {
    setItems(prev => prev.filter(i => i.alat_id !== alatId));
  };

  const handleConfirmDelete = () => {
    if (!confirmAlat) { setConfirmOpen(false); return; }
    setConfirmOpen(false);
    setRemovingId(confirmAlat);
    setTimeout(() => {
      removeItem(confirmAlat);
      setRemovingId(null);
      toast.success('Alat dihapus dari daftar');
      setConfirmAlat(null);
    }, 260);
  };

  const updateItem = (alatId, field, val) => {
    setItems(prev => prev.map(item => {
      if (item.alat_id === alatId) {
        const updated = { ...item, [field]: val };
        if (field === 'tanggal_mulai' && updated.tanggal_selesai < val) {
          updated.tanggal_selesai = val;
        }
        return updated;
      }
      return item;
    }));
  };

  const adaKonflik = Object.keys(konflik).length > 0;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!customerForm.nama || !customerForm.email) {
      return toast.error('Nama Lengkap & Email Customer wajib diisi');
    }
    for (const item of items) {
      if (getItemDurasi(item) <= 0) {
        const alat = getAlat(item.alat_id);
        return toast.error(`Tanggal sewa untuk ${alat?.nama_alat || 'alat'} tidak valid`);
      }
    }
    if (adaKonflik) {
      return toast.error('Ada alat yang tidak tersedia di tanggal yang dipilih.');
    }
    if (!ttdCustomer) {
      return toast.error('Tanda tangan digital Customer wajib diisi');
    }

    setLoading(true);
    try {
      const payload = {
        nama: customerForm.nama,
        email: customerForm.email,
        nik: customerForm.nik,
        no_hp: customerForm.no_hp,
        alamat: customerForm.alamat,
        kontak_darurat_nama: customerForm.kontak_darurat_nama,
        kontak_darurat_hp: customerForm.kontak_darurat_hp,
        tanggal_mulai: items[0]?.tanggal_mulai || today,
        tanggal_selesai: items[0]?.tanggal_selesai || tomorrow,
        opsi_pembayaran: opsiPembayaran,
        jumlah_dp: getJumlahDp(),
        jam_mulai: jamMulai,
        jam_selesai: jamSelesai,
        uang_jaminan: uangJaminan,
        jenis_jaminan: jenisJaminan,
        tanda_tangan_customer: ttdCustomer,
        tanda_tangan_admin: ttdAdmin,
        catatan,
        items: items.map(i => ({
          alat_id: i.alat_id,
          qty: i.qty,
          tanggal_mulai: i.tanggal_mulai,
          tanggal_selesai: i.tanggal_selesai,
          kelengkapan: i.kelengkapan,
        })),
      };

      const res = await api.post('/bookings', payload);
      toast.success('Formulir booking berhasil dibuat & ditandatangani!');
      navigate(`/bookings/${res.data.data.id}`);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Gagal membuat booking');
    }
    setLoading(false);
  };

  return (
    <AppLayout title="Formulir Penyewaan Alat">
      <div className="animate-fade-in max-w-4xl mx-auto space-y-6">
        <button onClick={() => navigate('/alat')}
          className="flex items-center gap-2 text-gray-500 hover:text-gray-800 text-sm font-medium transition-colors">
          <ArrowLeft className="h-4 w-4" /> Kembali ke katalog
        </button>

        {/* Form Title Banner */}
        <div className="p-6 rounded-3xl bg-gradient-to-r from-indigo-700 via-indigo-600 to-violet-600 text-white shadow-xl">
          <div className="flex items-center gap-3 mb-2">
            <FileCheck className="h-8 w-8 text-indigo-200" />
            <h1 className="text-2xl font-extrabold text-white">Formulir Penyewaan Alat Resmi</h1>
          </div>
          <p className="text-indigo-100 text-sm">Lengkapi identitas penyewa, rincian alat, waktu sewa, jaminan, dan tanda tangan digital.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">

          {/* SECTION A: Data Identitas Penyewa (Customer) */}
          <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
            <div className="flex items-center justify-between border-b border-gray-100 pb-3">
              <h2 className="text-base font-bold text-gray-900 flex items-center gap-2">
                <UserCheck className="h-5 w-5 text-indigo-600" /> A. Data Identitas Penyewa (Customer)
              </h2>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-1">
              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Nama Lengkap (sesuai KTP/KITAS) *</label>
                <input
                  type="text"
                  required
                  value={customerForm.nama}
                  onChange={e => setCustomerForm({ ...customerForm, nama: e.target.value })}
                  placeholder="Budi Santoso"
                  className="w-full px-3.5 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">NIK / No. Identitas *</label>
                <input
                  type="text"
                  required
                  value={customerForm.nik}
                  onChange={e => setCustomerForm({ ...customerForm, nik: e.target.value })}
                  placeholder="3171012345670001"
                  className="w-full px-3.5 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Nomor HP / WhatsApp *</label>
                <input
                  type="text"
                  required
                  value={customerForm.no_hp}
                  onChange={e => setCustomerForm({ ...customerForm, no_hp: e.target.value })}
                  placeholder="081234567890"
                  className="w-full px-3.5 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Alamat Email *</label>
                <input
                  type="email"
                  required
                  value={customerForm.email}
                  onChange={e => setCustomerForm({ ...customerForm, email: e.target.value })}
                  placeholder="budi@example.com"
                  className="w-full px-3.5 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">Alamat Domisili / Tempat Tinggal</label>
              <textarea
                rows={2}
                value={customerForm.alamat}
                onChange={e => setCustomerForm({ ...customerForm, alamat: e.target.value })}
                placeholder="Jl. Merdeka No. 123, Jakarta"
                className="w-full px-3.5 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500"
              />
            </div>

            {/* Kontak Darurat */}
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-200/80 space-y-3">
              <p className="text-xs font-bold text-gray-800 uppercase tracking-wider">Kontak Darurat (Keluarga / Kerabat Terdekat)</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">Nama Kontak Darurat</label>
                  <input
                    type="text"
                    value={customerForm.kontak_darurat_nama}
                    onChange={e => setCustomerForm({ ...customerForm, kontak_darurat_nama: e.target.value })}
                    placeholder="Siti Rahma (Istri / Orang Tua)"
                    className="w-full px-3 py-1.5 bg-white border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-indigo-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">No. HP Kontak Darurat</label>
                  <input
                    type="text"
                    value={customerForm.kontak_darurat_hp}
                    onChange={e => setCustomerForm({ ...customerForm, kontak_darurat_hp: e.target.value })}
                    placeholder="089876543210"
                    className="w-full px-3 py-1.5 bg-white border border-gray-200 rounded-xl text-xs focus:ring-2 focus:ring-indigo-500"
                  />
                </div>
              </div>
            </div>
          </div>


          {/* SECTION B: Detail Alat yang Disewa */}
          <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
            <div className="flex items-center justify-between border-b border-gray-100 pb-3">
              <h2 className="text-base font-bold text-gray-900 flex items-center gap-2">
                <Package className="h-5 w-5 text-indigo-600" /> B. Detail Alat yang Disewa
              </h2>
              {checking && (
                <span className="text-xs text-indigo-600 flex items-center gap-1">
                  <RefreshCw className="h-3 w-3 animate-spin" /> Memeriksa ketersediaan...
                </span>
              )}
            </div>

            <div className="space-y-4">
              {items.map(item => {
                const alat = getAlat(item.alat_id);
                const d = getItemDurasi(item);
                const subtotal = getItemSubtotal(item);
                const ada = konflik[item.alat_id];

                return (
                  <div key={item.alat_id} className={`p-4 rounded-2xl border transition-all ${
                    ada ? 'border-red-200 bg-red-50/50' : 'border-gray-100 bg-gray-50/50 hover:bg-white'
                  }`}>
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-200/60 pb-3">
                      <div className="flex items-center gap-3.5">
                        <div className="w-14 h-14 rounded-xl overflow-hidden bg-white flex-shrink-0 flex items-center justify-center border border-gray-200">
                          {alat?.gambar
                            ? <img src={`${IMAGE_BASE}/${alat.gambar}`} alt={alat.nama_alat} className="w-full h-full object-cover" />
                            : <Package className="h-6 w-6 text-gray-400" />
                          }
                        </div>
                        <div>
                          <p className="font-bold text-gray-900 text-sm">{alat?.nama_alat || `Alat #${item.alat_id}`}</p>
                          <p className="text-xs text-gray-500 font-mono">Kode Alat: {alat?.kode_alat || '-'}</p>
                          <p className="text-xs text-gray-500 mt-0.5">
                            {item.qty} unit × Rp {alat ? Number(alat.harga_sewa).toLocaleString('id-ID') : 0} / hari
                          </p>
                        </div>
                      </div>

                      <div className="flex items-center justify-between sm:justify-end gap-3">
                        <div className="text-right">
                          <p className="font-extrabold text-indigo-600 text-sm">Rp {subtotal.toLocaleString('id-ID')}</p>
                          <p className="text-[11px] text-gray-400">{d} hari sewa</p>
                        </div>
                        <button type="button" onClick={() => handleDeleteClick(item.alat_id)}
