                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          <ConfirmDialog
            isOpen={confirmOpen}
            onClose={() => setConfirmOpen(false)}
            onConfirm={handleConfirmDelete}
            title="Hapus alat dari daftar?"
            message="Alat akan dihapus dari daftar booking."
          />


          {/* SECTION C: Waktu dan Jam Sewa */}
          <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-4">
            <h2 className="text-base font-bold text-gray-900 flex items-center gap-2 border-b border-gray-100 pb-3">
              <Clock className="h-5 w-5 text-indigo-600" /> C. Jam Operasional & Pengambilan Alat
            </h2>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Jam Ambil / Mulai (WIB) *</label>
                <input
                  type="time"
                  required
                  value={jamMulai}
                  onChange={e => setJamMulai(e.target.value)}
                  className="w-full px-3.5 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Jam Selesai / Kembali (WIB) *</label>
                <input
                  type="time"
                  required
                  value={jamSelesai}
                  onChange={e => setJamSelesai(e.target.value)}
