        >
          {selectedBooking && (
            <div className="space-y-6">
              {/* Progress Tracker Status Pembayaran */}
              <div className="bg-slate-50 rounded-2xl p-5 border border-gray-100">
                <p className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-4">
